arguments.command:
curl -s -X POST https://api.linear.app/graphql -H 'Content-Type: application/json' -d '{"query":"{ __type(name: \"Mutation\") { fields { name args { name type { name kind ofType { name } } } } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
for f in d['data']['__type']['fields']:
    if f['name']=='cycleUpdate':
        print(f['name'], [(a['name'], str(a['type'])) for a in f['args']])"

